package net.civeira.phylax.common.infrastructure.connector.quarkus.mutiny;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.atomic.AtomicReference;
import java.util.stream.Stream;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

import io.opentelemetry.api.OpenTelemetry;
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.SpanContext;
import io.opentelemetry.api.trace.TraceFlags;
import io.opentelemetry.api.trace.TraceState;
import io.opentelemetry.api.trace.Tracer;
import io.opentelemetry.context.Scope;
import io.vertx.core.http.HttpServer;
import io.vertx.core.json.JsonObject;
import io.vertx.mutiny.core.Vertx;
import io.vertx.mutiny.ext.web.client.WebClient;
import net.civeira.phylax.common.infrastructure.connector.RemoteConnection;
import net.civeira.phylax.common.infrastructure.connector.RemoteQuery;

@DisplayName("Mutiny web connector")
class MutinyWebConnectorUnitTest {
  private static final Tracer TRACER = OpenTelemetry.noop().getTracer("test");

  private static Vertx vertx;
  private static HttpServer server;
  private static String base;

  /**
   * Starts a local server that answers "/text" with plain text, "/fail" with 500 and anything else
   * with a json echo of the request.
   */
  @BeforeAll
  static void startServer() throws Exception {
    vertx = Vertx.vertx();
    server =
        vertx.getDelegate().createHttpServer().requestHandler(req -> req.body().onSuccess(body -> {
          if ("/text".equals(req.path())) {
            req.response().putHeader("Content-Type", "text/plain").end("hello");
          } else if ("/fail".equals(req.path())) {
            req.response().setStatusCode(500).end("{}");
          } else {
            req.response().putHeader("Content-Type", "application/json")
                .end(new JsonObject().put("method", req.method().name()).put("path", req.path())
                    .put("query", String.valueOf(req.query()))
                    .put("accept", req.getHeader("Accept"))
                    .put("contentType", String.valueOf(req.getHeader("Content-Type")))
                    .put("trace", String.valueOf(req.getHeader("X-Trace")))
                    .put("body", body.toString()).encode());
          }
        })).listen(0).toCompletionStage().toCompletableFuture().get();
    base = "http://localhost:" + server.actualPort();
  }

  @AfterAll
  static void stopServer() {
    vertx.closeAndAwait();
  }

  private static Span validParent() {
    return Span.wrap(SpanContext.create("0af7651916cd43dd8448eb211c80319c", "b7ad6b7169203331",
        TraceFlags.getSampled(), TraceState.getDefault()));
  }

  @Nested
  @DisplayName("Requests")
  class Requests {
    private final MutinyWebConnector connector = new MutinyWebConnector(vertx, TRACER);

    @Test
    @DisplayName("Should send a GET with query params and headers and read text")
    void shouldGetText() {
      AtomicReference<String> text = new AtomicReference<>();

      connector.send(connector.get(base + "/text").queryParam("a", "1").queryParam(Map.of("b", "2"))
          .header("X-Trace", "t").headers(Map.of("X-Other", List.of("o")))
          .processor(String.class, text::set));

      assertEquals("hello", text.get());
    }

    @Test
    @DisplayName("Should send a GET as json and parse the response")
    @SuppressWarnings("rawtypes")
    void shouldGetJson() {
      AtomicReference<Map> echo = new AtomicReference<>();

      connector.send(List.of(connector.get(base + "/echo").queryParam("a", "1")
          .header("X-Trace", List.of("t1")).processor(Map.class, echo::set)));

      assertEquals("GET", echo.get().get("method"));
      assertEquals("a=1", echo.get().get("query"));
      assertEquals("application/json", echo.get().get("accept"));
      assertEquals("application/json", echo.get().get("contentType"));
      assertEquals("t1", echo.get().get("trace"));
    }

    @Test
    @DisplayName("Should send json bodies and run several requests together")
    @SuppressWarnings("rawtypes")
    void shouldSendBodies() {
      AtomicReference<Map> post = new AtomicReference<>();
      Queue<String> done = new ConcurrentLinkedQueue<>();

      connector.send(
          connector.post(base + "/echo", Map.of("name", "ana")).processor(Map.class, post::set),
          connector.put(base + "/echo", Map.of("n", 1)).processor(() -> done.add("put")),
          connector.patch(base + "/echo", Map.of("n", 2)).processor(() -> done.add("patch")));
      connector
          .send(Stream.of(connector.delete(base + "/echo").processor(() -> done.add("delete"))));

      assertEquals("POST", post.get().get("method"));
      assertEquals("{\"name\":\"ana\"}", post.get().get("body"));
      assertEquals(Set.of("put", "patch", "delete"), Set.copyOf(done));
    }

    @Test
    @DisplayName("Should do nothing for an empty batch")
    void shouldIgnoreEmptyBatch() {
      assertDoesNotThrow(() -> connector.send(List.of()));
    }

    @Test
    @DisplayName("Should expand path params of the target template")
    @SuppressWarnings("rawtypes")
    void shouldExpandPathParams() {
      AtomicReference<Map> single = new AtomicReference<>();
      AtomicReference<Map> many = new AtomicReference<>();
      RemoteQuery query = connector.get(base + "/items/{id}");
      assertSame(query, query.pathParam("id", "7"));

      connector.send(query.processor(Map.class, single::set),
          connector.get(base + "/items/{kind}/{id}").pathParam(Map.of("kind", "a", "id", "8"))
              .processor(Map.class, many::set));

      assertEquals("/items/7", single.get().get("path"));
      assertEquals("/items/a/8", many.get().get("path"));
    }
  }

  @Nested
  @DisplayName("Tracing")
  class Tracing {

    @Test
    @DisplayName("Should trace successful and failed responses under a valid parent span")
    @SuppressWarnings("rawtypes")
    void shouldTraceUnderParent() {
      MutinyWebConnector connector = new MutinyWebConnector(vertx, TRACER);
      AtomicReference<Map> echo = new AtomicReference<>();
      AtomicReference<String> failed = new AtomicReference<>();

      try (Scope ignored = validParent().makeCurrent()) {
        connector
            .send(connector.post(base + "/echo", Map.of("k", "v")).processor(Map.class, echo::set));
        connector.send(connector.get(base + "/fail").processor(String.class, failed::set));
      }

      assertEquals("POST", echo.get().get("method"));
      assertEquals("{}", failed.get());
    }

    @Test
    @DisplayName("Should record transport failures on the span and propagate them")
    void shouldTraceTransportFailures() {
      MutinyWebConnector connector = new MutinyWebConnector(vertx, TRACER);
      RemoteConnection unreachable;
      try (Scope ignored = validParent().makeCurrent()) {
        unreachable = connector.get("http://localhost:1/none").processor(String.class, _ -> {
        });
      }

      assertThrows(RuntimeException.class, () -> connector.send(unreachable));
    }

    @Test
    @DisplayName("Should not trace without a tracer")
    void shouldNotTraceWithoutTracer() {
      MutinyWebConnector connector = new MutinyWebConnector(vertx, null);
      AtomicReference<String> text = new AtomicReference<>();

      try (Scope ignored = validParent().makeCurrent()) {
        connector.send(connector.get(base + "/text").processor(String.class, text::set));
      }

      assertEquals("hello", text.get());
    }
  }

  @Nested
  @DisplayName("Target parsing")
  class Targets {
    private final WebClient client = WebClient.create(vertx);

    @Test
    @DisplayName("Should keep the query of the target next to the added params")
    @SuppressWarnings("rawtypes")
    void shouldKeepTargetQuery() {
      AtomicReference<Map> echo = new AtomicReference<>();

      new MutinyWebConnector(vertx, null)
          .send(MutinyWebQuery.create(null, client, null, base + "/echo?x=1", null)
              .queryParam("a", "2").processor(Map.class, echo::set));

      assertEquals("x=1&a=2", echo.get().get("query"));
    }

    @Test
    @DisplayName("Should build relative and https targets")
    void shouldAcceptRelativeTargets() {
      assertTrue(MutinyWebQuery.create(TRACER, client, MutinyWebQuery.Method.POST, "/items/{id}",
          Map.of()) instanceof RemoteQuery);
      assertTrue(MutinyWebQuery.create(TRACER, client, null, "https://example.org/items/{id}",
          null) instanceof RemoteQuery);
    }

    @Test
    @DisplayName("Should reject targets that are not valid templates")
    void shouldRejectInvalidTemplates() {
      assertThrows(IllegalArgumentException.class,
          () -> MutinyWebQuery.create(TRACER, client, null, base + "/not a template", null));
    }
  }
}
